def lzw(s):
    if not s:
        return ""
    s = " " + s
    stack = []
    for c in s:
        if c != " ":
            stack.append(c)
            continue
        if len(stack) > 2:
            stack.append(stack[-len(stack) + 1])
            stack.pop()
    return "".join(stack)
```

